def aggressive_cows_brute(stalls: list[int], k: int) -> int:
    stalls.sort()
    best = 0
    for d in range(1, stalls[-1] - stalls[0] + 1):
        count, last = 1, stalls[0]
        for s in stalls[1:]:
            if s - last >= d:
                count += 1
                last = s
        if count >= k:
            best = d
    return best

def aggressive_cows(stalls: list[int], k: int) -> int:
    stalls.sort()

    def can_place(d: int) -> bool:
        count, last = 1, stalls[0]
        for s in stalls[1:]:
            if s - last >= d:
                count += 1
                last = s
                if count >= k:
                    return True
        return count >= k

    lo, hi, ans = 1, stalls[-1] - stalls[0], 0
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if can_place(mid):
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return ans
